import { cacheLife, cacheTag } from 'next/cache'

export type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function fetchDashboard(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')

  if (!res.ok) {
    throw new Error(`Dashboard request failed with status ${res.status}`)
  }

  return res.json()
}

// Aggregates are the same for every visitor, so they get a cache lifetime and
// become part of the prerendered shell instead of a request-time hole.
export async function getDashboardSummary() {
  'use cache'
  cacheLife('minutes')
  cacheTag('dashboard')

  const { totalRevenue, totalInvoices, revenue } = await fetchDashboard()
  return { totalRevenue, totalInvoices, revenue }
}

// Invoices must reflect the latest writes, so this stays uncached and streams
// in behind its <Suspense> fallback at request time.
export async function getLatestInvoices() {
  const { invoices } = await fetchDashboard()
  return invoices
}

