import { cache } from 'react'

export type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

// One request per render pass, shared by every section that needs it.
const fetchDashboard = cache(async (): Promise<DashboardData> => {
  const res = await fetch('https://api.example.com/dashboard')

  if (!res.ok) {
    throw new Error(`Dashboard request failed with status ${res.status}`)
  }

  return res.json()
})

// Uncached reads: each one is awaited inside its own <Suspense> boundary, so the
// shell is prerendered and these stream in at request time.
//
// To move a section into the shell instead, give its function a lifetime:
//
//   export async function getCardStats() {
//     'use cache'
//     cacheLife('minutes')
//     ...
//   }
//
// That requires the endpoint to be reachable during `next build`, since the
// prerender resolves it there.

export async function getCardStats() {
  const { totalRevenue, totalInvoices } = await fetchDashboard()
  return { totalRevenue, totalInvoices }
}

export async function getRevenue() {
  const { revenue } = await fetchDashboard()
  return revenue
}

export async function getLatestInvoices() {
  const { invoices } = await fetchDashboard()
  return invoices
}

